/*
 * Reading data/cantonal-parliaments.json (generated by `npm run cantonal-parliaments` from the OFS table
 * je-f-17.02.05.01.03): seats per party at the latest election of a canton's parliament.
 * Shared by the site and by `npm run check`.
 */
import type { CantonalParliamentRow, CantonalParliaments } from "../types.ts";

export const YEAR_COLUMN = "Année électorale";
export const TOTAL_COLUMN = "Total";

/** A label of the table without its footnote mark and outer spaces: "Vaud 7) " -> "Vaud", "\u00a0\u00a0VERT-E-S 9)" -> "VERT-E-S". */
export function plainLabel(label: string): string {
  return label.replace(/\u00a0/g, " ").replace(/\s+\d+\)\s*$/, "").trim();
}

/** A cell's seat count, or null when the cell holds no number ("*": no list, "…": not available, absent). */
export function seatCount(text: string | undefined): number | null {
  const t = text?.replace(/\u00a0/g, " ").trim() ?? "";
  return /^\d+$/.test(t) ? Number(t) : null;
}

/** The row of a canton, found by the canton's name in data/territories.json. */
export function cantonRow(p: CantonalParliaments, name: string): CantonalParliamentRow | undefined {
  return p.rows.find((r) => plainLabel(r.label) === name);
}

export interface PartySeats {
  /** Column label without its footnote mark ("PLR", "Autres"). */
  column: string;
  /** Party of the canton in parties.json, null when the site has none for this column. */
  partyId: string | null;
  seats: number;
}
export interface CantonSeats {
  year: number | null;
  /** The table's own total. */
  total: number | null;
  /** Columns with at least one seat, most seats first. */
  parties: PartySeats[];
}

/** Seats per party of one canton's parliament, at its latest election. */
export function cantonSeats(p: CantonalParliaments, code: string, row: CantonalParliamentRow): CantonSeats {
  const mapping = p.party_mapping[code] ?? {};
  let year: number | null = null;
  let total: number | null = null;
  const parties: PartySeats[] = [];
  for (const raw of p.columns) {
    const column = plainLabel(raw);
    const n = seatCount(row.cells[raw]);
    if (column === YEAR_COLUMN) year = n;
    else if (column === TOTAL_COLUMN) total = n;
    else if (n) parties.push({ column, partyId: mapping[column] ?? null, seats: n });
  }
  parties.sort((a, b) => b.seats - a.seats);
  return { year, total, parties };
}
